class SDIT(object):

    # SDIT
    def __init__(
        self,
        OBSERVATORY = None,
        INSTRUMENT = None,
        MEASUREMENT = None,
        WAVELENGTH_NM = float('nan'),
        IMAGE_ID = None,
        REQUESTED_AT = None,
        OBSERVED_AT = None,
        DATE_OBS = None,
        TIME_SCALE = None,
        CADENCE_S = float('nan'),
        EXPOSURE_S = float('nan'),
        IMAGE_CID = None,
        IMAGE_MEDIA_TYPE = None,
        IMAGE_DIGEST = None,
        IMAGE_SIZE_BYTES = 0,
        HEADER_CID = None,
        WIDTH = 0,
        HEIGHT = 0,
        CTYPE1 = None,
        CTYPE2 = None,
        CUNIT1 = None,
        CUNIT2 = None,
        CRPIX1 = float('nan'),
        CRPIX2 = float('nan'),
        CRVAL1 = float('nan'),
        CRVAL2 = float('nan'),
        CDELT1 = float('nan'),
        CDELT2 = float('nan'),
        CROTA2 = float('nan'),
        PC = None,
        RSUN_OBS_ARCSEC = float('nan'),
        RSUN_REF_M = float('nan'),
        DSUN_OBS_M = float('nan'),
        CRLN_OBS_DEG = float('nan'),
        CRLT_OBS_DEG = float('nan'),
        HGLN_OBS_DEG = float('nan'),
        HGLT_OBS_DEG = float('nan'),
        QUALITY = 0,
        HAS_QUALITY = False,
        PROCESSING = None,
        PROVENANCE = None,
        SOURCE_CID = None,
        SOURCE_DIGEST = None,
        RETRIEVED_AT = None,
    ):
        self.OBSERVATORY = OBSERVATORY  # type: Optional[str]
        self.INSTRUMENT = INSTRUMENT  # type: Optional[str]
        self.MEASUREMENT = MEASUREMENT  # type: Optional[str]
        self.WAVELENGTH_NM = WAVELENGTH_NM  # type: float
        self.IMAGE_ID = IMAGE_ID  # type: Optional[str]
        self.REQUESTED_AT = REQUESTED_AT  # type: Optional[str]
        self.OBSERVED_AT = OBSERVED_AT  # type: Optional[str]
        self.DATE_OBS = DATE_OBS  # type: Optional[str]
        self.TIME_SCALE = TIME_SCALE  # type: Optional[str]
        self.CADENCE_S = CADENCE_S  # type: float
        self.EXPOSURE_S = EXPOSURE_S  # type: float
        self.IMAGE_CID = IMAGE_CID  # type: Optional[str]
        self.IMAGE_MEDIA_TYPE = IMAGE_MEDIA_TYPE  # type: Optional[str]
        self.IMAGE_DIGEST = IMAGE_DIGEST  # type: Optional[str]
        self.IMAGE_SIZE_BYTES = IMAGE_SIZE_BYTES  # type: int
        self.HEADER_CID = HEADER_CID  # type: Optional[str]
        self.WIDTH = WIDTH  # type: int
